const px=(p,on='')=>{const[m,c]=PJ[p];let r='';SP[m].forEach((l,y)=>[...l].forEach((k,x)=>{if(k!='.')r+=`<rect x="${x}" y="${y}" width="1" height="1"/>`}));return `<svg class="px ${on}" viewBox="0 0 8 8" fill="${c}" aria-hidden="true">${r}</svg>`};
