function fit(){const f=q('#fit'),w=f.firstElementChild;if(!w)return;const W=w.offsetWidth,H=w.offsetHeight,k=Math.min((f.clientWidth-40)/W,(f.clientHeight-4)/H,1);w.style.transform=`scale(${k})`;w.style.marginRight=`${-(W*(1-k))}px`;w.style.marginBottom=`${-(H*(1-k))}px`}
function show(){const s=cur,r=(mode=='now'&&s.now)||s.after;q('#fit').innerHTML=r();const w=q('#fit .win');if(hi&&s.now&&mode=='after')w.classList.add('hi');
 q('#bar').innerHTML=`<b>${s.t}</b>${s.now?`<span class=seg><button data-m=now class="${mode=='now'?'on':''}">Now</button><button data-m=after class="${mode=='after'?'on':''}">Proposed</button></span><button class=gb data-hi>${hi?'Hide':'Show'} change outlines</button>`:'<span style="font-size:12px;color:var(--t3)">New screen</span>'}<span class=sp></span><button class=gb data-all>All screens</button><button class=gb data-th>Light / dark</button><button class=gb data-d=-1 aria-label="Previous screen">${ic('chevron-left')}</button><button class=gb data-d=1 aria-label="Next screen">${ic('chevron-right')}</button>`;
 q('#notes').innerHTML=`<div><p>${s.d}</p>${s.v?`<p class=v>${s.v.startsWith('New')?'':'Refined: '}${s.v}</p>`:''}</div><ul>${s.r.map(x=>`<li>${x}</li>`).join('')}</ul>`;
 document.querySelectorAll('#nav .l').forEach(b=>b.setAttribute('aria-current',b.dataset.go==s.id));document.querySelector('#nav [aria-current=true]')?.scrollIntoView({block:'nearest'});fit()}
function go(id){const s=L.find(x=>x.id==id);if(!s)return;cur=s;mode='after';document.body.classList.remove('all');history.replaceState(0,'','#'+id);show()}
q('#nav').innerHTML=`<h1>${hub(16)}Master</h1><p class=tg>Version 2. ${L.filter(x=>x.now).length} changed screens, ${L.filter(x=>!x.now).length} new</p>`+S.map(x=>x.id?`<button class=l data-go=${x.id}><span>${L.indexOf(x)+1}</span>${x.t}</button>`:`<h2>${x[0]}</h2>`).join('');
function all(){document.body.classList.toggle('all');if(!document.body.classList.contains('all'))return;let h='';S.forEach(x=>{if(!x.id){h+=(h?'</div>':'')+`<h2>${x[0]}</h2><div class=grid>`}else h+=`<div class=th role=button tabindex=0 data-go=${x.id}><div class=box>${x.after()}</div><span>${L.indexOf(x)+1}. ${x.t}</span></div>`});q('#all').innerHTML=h+'</div>';document.querySelectorAll('.th .box').forEach(b=>{const w=b.firstElementChild;w.style.transform=`scale(${b.clientWidth/1400})`;w.inert=true})}
document.addEventListener('click',e=>{const t=e.target.closest('[data-go],[data-m],[data-hi],[data-all],[data-th],[data-d]');if(!t)return;const d=t.dataset;if(d.go)go(t.closest('.th')?t.closest('.th').dataset.go:d.go);else if(d.m){mode=d.m;show()}else if('hi' in d){hi=!hi;show()}else if('all' in d)all();else if('th' in d)document.documentElement.classList.toggle('light');else if(d.d)go(L[(L.indexOf(cur)+ +d.d+L.length)%L.length].id)});
